INSERT INTO repo_cf_skills (cf_skill_id, education_level, sub_heading, text, status) VALUES ('CFS_SDG01_TER_016', 'Tertiary education', 'Poverty reduction and sustainable solutions', 'Develop adaptive strategies to mitigate poverty impacts during disasters, health crises, and economic shocks.', 'Active'), ('CFS_SDG01_ADULT_001', 'Adult education', 'Financial literacy and planning', 'Apply basic financial skills, including budgeting for household needs, planning for savings and managing loans; and understanding income, expenses, credit, debt and interest rates.', 'Active'), ('CFS_SDG01_ADULT_002', 'Adult education', 'Financial literacy and planning', 'Practise budgeting and financial planning tools through real-life examples.', 'Active'), ('CFS_SDG01_ADULT_003', 'Adult education', 'Financial literacy and planning', 'Recognise the importance of saving regularly and borrowing responsibly.', 'Active'), ('CFS_SDG01_ADULT_004', 'Adult education', 'Access to financial services', 'Open a savings account, access micro-loans and engage with local financial institutions. Participate in savings groups or co-operatives. Access mobile banking or community credit facilities.', 'Active'), ('CFS_SDG01_ADULT_005', 'Adult education', 'Access to financial services', 'Understand economic rights to land, property, work opportunities and entrepreneurship.', 'Active'), ('CFS_SDG01_ADULT_006', 'Adult education', 'Income generation and business skills', 'Identify and plan small-scale income-generating activities based on community needs and personal strengths.', 'Active'), ('CFS_SDG01_ADULT_007', 'Adult education', 'Income generation and business skills', 'Apply basic entrepreneurship and marketing skills, such as customer service, simple pricing, record-keeping and packaging.', 'Active'), ('CFS_SDG01_ADULT_008', 'Adult education', 'Income generation and business skills', 'Access markets, work in co-operatives, or start community enterprises.', 'Active'), ('CFS_SDG01_ADULT_009', 'Adult education', 'Income generation and business skills', 'Understand the use of small loans and how to make informed decisions about borrowing.', 'Active'), ('CFS_SDG01_ADULT_010', 'Adult education', 'Income generation and business skills', 'Examine economic resilience strategies, such as diversifying income sources, seasonal employment, skills-building and self-employment.', 'Active'), ('CFS_SDG01_ADULT_011', 'Adult education', 'Communication and collaboration', 'Build confidence and communication skills to participate in financial decisions at home and in the community.', 'Active'), ('CFS_SDG01_ADULT_012', 'Adult education', 'Communication and collaboration', 'Practise negotiation and collaboration for shared business ventures or community development.', 'Active'), ('CFS_SDG01_ADULT_013', 'Adult education', 'Communication and collaboration', 'Engage in community discussions, decision-making and local development planning.', 'Active'), ('CFS_SDG01_ADULT_014', 'Adult education', 'Communication and collaboration', 'Discuss how to collaborate with development agencies and government support programmes.', 'Active'), ('CFS_SDG02_SEC_001', 'Secondary education', 'Food planning and analysis', 'Plan and evaluate balanced meals based on geographical, seasonal, economic and nutritional considerations.', 'Active'), ('CFS_SDG02_SEC_002', 'Secondary education', 'Food planning and analysis', 'Use graphs, tables and charts to analyse the energy and nutritional value of food types.', 'Active'), ('CFS_SDG02_SEC_003', 'Secondary education', 'Food planning and analysis', 'Assess ingredient sourcing for sustainability and environmental impact.', 'Active'), ('CFS_SDG02_SEC_004', 'Secondary education', 'Practical food and environmental skills', 'Select, prepare and store food using methods that optimise nutrition and minimise waste.', 'Active'), ('CFS_SDG02_SEC_005', 'Secondary education', 'Practical food and environmental skills', 'Participate in gardening, food preparation and preservation projects that promote healthy and sustainable eating habits.', 'Active'), ('CFS_SDG02_SEC_006', 'Secondary education', 'Practical food and environmental skills', 'Investigate local and global food supply chains and identify challenges such as overproduction, access and inequality.', 'Active'), ('CFS_SDG02_SEC_007', 'Secondary education', 'Action and advocacy', 'Develop and implement social action plans focused on hunger, nutrition or food justice.', 'Active'), ('CFS_SDG02_SEC_008', 'Secondary education', 'Action and advocacy', 'Participate in school or community-based food literacy initiatives, such as cooking clubs, gardening programmes or nutrition campaigns.', 'Active'), ('CFS_SDG02_SEC_009', 'Secondary education', 'Action and advocacy', 'Integrate indigenous knowledge into educational and sustainability projects.', 'Active'), ('CFS_SDG02_SEC_010', 'Secondary education', 'Action and advocacy', 'Research and propose local and global solutions to hunger-related issues, using data and policy evaluation tools.', 'Active'), ('CFS_SDG02_TVET_001', 'TVET', 'Agricultural practice and management', 'Implement sustainable farming methods such as agroecology, crop rotation and organic techniques to improve productivity and environmental outcomes.', 'Active'), ('CFS_SDG02_TVET_002', 'TVET', 'Agricultural practice and management', 'Apply farm management skills including resource planning, budgeting, risk management and productivity tracking to enhance operational success.', 'Active'), ('CFS_SDG02_TVET_003', 'TVET', 'Food safety and processing', 'Design and operate supply chain food safety management systems to meet standards across production, processing and retail.', 'Active'), ('CFS_SDG02_TVET_004', 'TVET', 'Food safety and processing', 'Develop skills in food preservation, processing and packaging to enhance product value and safety.', 'Active'), ('CFS_SDG02_TVET_005', 'TVET', 'Business development and innovation', 'Apply entrepreneurial thinking to develop agribusiness ventures, including food tourism and artisanal food products.', 'Active'), ('CFS_SDG02_TVET_006', 'TVET', 'Business development and innovation', 'Conduct market analysis and develop business plans that incorporate marketing, distribution and sustainability strategies.', 'Active'), ('CFS_SDG02_TVET_007', 'TVET', 'Business development and innovation', 'Engage in training and business simulations to strengthen decision-making, innovation and customer engagement skills.', 'Active'), ('CFS_SDG02_TVET_008', 'TVET', 'Community engagement and food access', 'Plan, manage and evaluate food gardens or community-based agricultural initiatives to combat hunger and improve food security.', 'Active'), ('CFS_SDG02_TVET_009', 'TVET', 'Community engagement and food access', 'Collaborate with local organisations and stakeholders to implement food security programmes and nutrition education campaigns.', 'Active'), ('CFS_SDG02_TER_001', 'Tertiary education', 'Sustainable agricultural practices', 'Design and implement sustainable and climate-smart agricultural systems (for example, agroecology, crop rotation, integrated pest management) that enhance food production and resilience.', 'Active'), ('CFS_SDG02_TER_002', 'Tertiary education', 'Sustainable agricultural practices', 'Apply techniques for water conservation, soil health improvement and biodiversity protection within food production systems.', 'Active'), ('CFS_SDG02_TER_003', 'Tertiary education', 'Food safety and farm management', 'Develop and monitor food safety management systems aligned with international standards to ensure quality control across the food supply chain.', 'Active'), ('CFS_SDG02_TER_004', 'Tertiary education', 'Food safety and farm management', 'Apply farm management principles, including budgeting, business planning, resource allocation and risk management, to improve agricultural viability and efficiency.', 'Active'), ('CFS_SDG02_TER_005', 'Tertiary education', 'Business and entrepreneurship', 'Develop food processing and value addition skills to create innovative, market-ready products.', 'Active'), ('CFS_SDG02_TER_006', 'Tertiary education', 'Business and entrepreneurship', 'Use business tools such as market analysis, value chain mapping and marketing strategy to launch and manage food enterprises, including those linked to food tourism and artisanal production.', 'Active'), ('CFS_SDG02_TER_007', 'Tertiary education', 'Community development and policy leadership', 'Plan and manage local food production projects, such as community gardens or urban agriculture, aimed at improving food access and nutrition.', 'Active'), ('CFS_SDG02_TER_008', 'Tertiary education', 'Community development and policy leadership', 'Engage in policy-making simulations and case studies to propose evidence-based solutions to food security challenges.', 'Active'), ('CFS_SDG02_TER_009', 'Tertiary education', 'Community development and policy leadership', 'Conduct academic research on food system issues, climate impacts and sustainable agricultural practices using qualitative and quantitative tools.', 'Active'), ('CFS_SDG02_TER_010', 'Tertiary education', 'Analytical and research competence', 'Use research methodologies and data analysis to evaluate food security conditions, identify trends and recommend policy or programmatic responses.', 'Active'), ('CFS_SDG02_TER_011', 'Tertiary education', 'Analytical and research competence', 'Contribute to innovation in agriculture by analysing the performance of sustainable practices and proposing refinements based on field data and community needs.', 'Active'), ('CFS_SDG02_ADULT_001', 'Adult education', 'Sustainable and adaptive farming practices', 'Apply basic sustainable farming techniques, such as agroecology, composting, intercropping and crop rotation, to improve soil health and increase yields.', 'Active'), ('CFS_SDG02_ADULT_002', 'Adult education', 'Sustainable and adaptive farming practices', 'Manage mixed farming systems effectively, combining crops, livestock and tree planting for balanced nutrition and diversified income.', 'Active'), ('CFS_SDG02_ADULT_003', 'Adult education', 'Nutrition and food security at home and in the community', 'Establish home and community vegetable gardens that integrate nutrition education, especially targeting women and caregivers.', 'Active'), ('CFS_SDG02_ADULT_004', 'Adult education', 'Nutrition and food security at home and in the community', 'Implement simple food hygiene and safety practices in food handling, storage and processing to reduce illness and waste.', 'Active'), ('CFS_SDG02_ADULT_005', 'Adult education', 'Farm and financial management', 'Improve farm planning and budgeting skills, including how to allocate resources, assess input costs and manage risks.', 'Active') ON CONFLICT DO NOTHING;